import java.util.*;
import java.util.stream.Collectors;

abstract class Vehicle {
    abstract double fuelEfficiency();
}

class Car extends Vehicle {
    private double distance;
    private double fuel;

    public Car(double distance, double fuel) {
        this.distance = distance;
        this.fuel = fuel;
    }

    @Override
    double fuelEfficiency() {
        return distance / fuel;
    }
}

class Truck extends Vehicle {
    private double distance;
    private double fuel;

    public Truck(double distance, double fuel) {
        this.distance = distance;
        this.fuel = fuel;
    }

    @Override
    double fuelEfficiency() {
        return (distance * 2) / fuel;
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String line = sc.nextLine().trim();
        sc.close();

        if (line.isEmpty()) {
            return;
        }

        List<String> parts = Arrays.stream(line.split("\\s+"))
                .filter(s -> !s.isEmpty())
                .collect(Collectors.toList());

        if (parts.size() < 3) {
            return;
        }

        String vehicleType = parts.get(0);
        double distance = Double.parseDouble(parts.get(1));
        double fuel = Double.parseDouble(parts.get(2));

        Vehicle v;
        switch (vehicleType) {
            case "Car":
                v = new Car(distance, fuel);
                break;
            case "Truck":
                v = new Truck(distance, fuel);
                break;
            default:
                return;
        }

        System.out.printf("Fuel Efficiency: %.1f%n", v.fuelEfficiency());
    }
}
